Web Portal (SPA).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Web Portal (SPA) container

Container_Boundary(web_portal_spa, "Web Portal (SPA)") {
    Component(Dynamic_Form_Renderer, "Dynamic Form Renderer", "React / TypeScript", "Renders dynamic claims forms and user interfaces for customers and brokers.")
    Component(Authentication_Client, "Authentication Client", "React / TypeScript / OIDC", "Manages user authentication sessions and integrates with Azure AD.")
    Component(API_Client, "API Client", "Axios / Fetch API", "Communicates securely with the Claims API (BFF) over REST and HTTPS.")
}

Rel(Dynamic_Form_Renderer, API_Client, "Sends user input and claims data")
Rel(Authentication_Client, API_Client, "Attaches OAuth 2.0 / OIDC tokens")

@enduml

Azure Service Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure Service Bus container

Container_Boundary(azure_service_bus, "Azure Service Bus") {
    Component(ClaimSubmissionTopic, "Claim Submission Topic", "Azure Service Bus Topic (Premium Tier)", "Enterprise messaging topic that receives published claim events from the Claims API.")
    Component(MainframeSyncQueue, "Mainframe Sync Queue", "Azure Service Bus Queue (Premium Tier)", "Queues synchronization payloads forwarded from the claim submission topic for consumption by the mainframe adapter.")
    Component(AuditArchiveSubscription, "Audit Archive Subscription", "Azure Service Bus Subscription", "Fans out event copies from the claim submission topic for archiving.")
}

Rel(ClaimSubmissionTopic, MainframeSyncQueue, "Forwards messages via subscriptions", "AMQP")
Rel(ClaimSubmissionTopic, AuditArchiveSubscription, "Fans out event copies", "AMQP")

@enduml

